                                    return '<a href="#" title="Activar" class="btn btn-default btn-xs confirm-turn" data-turn="true" data-id="'+ full.codigo_promocion +'" data-name="'+ full.tipo +'" data-action="activar"> <i class="fa fa-toggle-off"></i></a>';
