(function ($, window, document, undefined) {

    app.ReportConvocatoriaView = Backbone.View.extend({

        el: '#report-convocatoria-rutan-wrapper',
        //template: _.template( ($('#projects-list-tpl').html() || '') ),
        //templateConfirm: _.template( ($('#confirm-project-tpl').html() || '') ),
        templateConfirmExportData: _.template( ($('#confirm-export-data-tpl').html() || '') ),
        //templateButtonsAction: _.template( ($('#buttons-action-tpl').html() || '') ),
        events: {
            'submit #form-report-rutan-209': 'export_report',
            'submit #form-report-rutan-200': 'export_report',
            'submit #form-general_convocatoria_ruta_emprendimiento' : 'export_report',
            'submit #form-report-mentorias' : 'export_report',
            'submit #form-report-sessions-rutan' : 'export_report',


        },
        parameters: {
            dataFilter: {}
        },

        /**
         * Constructor Method
         */
        initialize : function(opts) {

            // Events Listener custome
            this.on( 'beforeRender', this.beforeRender );
            this.on( 'afterRender', this.afterRender );

            this.configAlert = {
                'wrapper': '#mentoring-wrapper',
                'closeTime': 4000,
                'speedOpen': 500,
                'speedClose': 500
            };

        },

        /*
         * Render View Element
         */
        render: function() {

            var attributes = {};
            //this.$el.html( this.template(attributes) );

            // Initialize attributes
            /*this.$searchState   = this.$('#codigo_estado');
            this.$searchIdentificacion  = this.$('#numero_identificacion');
            this.$searchNombre  = this.$('#nombre_proyecto');
            this.$formFilters   = this.$('#form-projects-filter');
            this.$searchStageProyect  = this.$('#codigo_etapa_proyecto');
            this.$searchCategoryProyect  = this.$('#codigo_categoria_proyecto');
            this.$searchCategoryProyect  = this.$('#codigo_categoria_proyecto');
            this.$projectsListSearchTable = this.$('#projects-list-search-table');
            this.$searchEntrepreneur  = this.$('#correo_electronico_emprendedor_filter_data');
            */
            // overwrite model id attribute
            this.referenceViews();
        },

        /**
         * reference to views
         */
        referenceViews: function () {
            var _this = this;
          
        },

        /**
        * Load spinner on the request
        */
        loadSpinner: function () {
           // window.Misc.setSpinner( this.$gridSearchTable );
        },

        search: function(e) {
            e.preventDefault();
           // this.projectsListSearchTable.ajax.reload();
        },

        clear: function(e) {
            e.preventDefault();
           /* this.$searchIdentificacion.val('');
            this.$searchNombre.val('');
            this.$searchEntrepreneur.val('');
            this.$searchStageProyect.select2('val', '');
            this.$searchCategoryProyect.select2('val', '');

            this.projectsListSearchTable.ajax.reload();*/
        },

        export_report: function(e) {
            console.log('Backbone metodo export_report');

            e.preventDefault();
            var current_id = e.target.id;
            window.Misc.setSpinner( '#'+current_id );

            var _this = this;

            if( this.acceptConfirm instanceof Backbone.View ) {
                this.acceptConfirm.stopListening();
                this.acceptConfirm.undelegateEvents();
                console.log('Backbone if export_report');
            }
            var data = window.Misc.formToJson( e.target )

            this.acceptConfirm = new app.ConfirmWindow({
                parameters: {
                    template: this.templateConfirmExportData({id_report: data.id_report}),
                    titleConfirm: "Confirmación",
                    onConfirm: function () {
                        $.ajax({
                            data: data,
                            url: window.Misc.urlFull( Route.route('reportes.rutan.convocatorias.store')),
                            type: 'post',
                            success: function (data, textStatus, jqXHR ) {
                                // complete proccess
                                window.Misc.removeSpinner({
                                    'wrap': '#'+current_id,
                                    'direct': false
                                });
                                
                                const text = data.success ? data.message : data.errors;
                                const type = data.success ? 'success' : 'alert';
                        
                                var config = {
                                    'text': text,
                                    'type': type
                                };
                        
                                _.extend( _this.configAlert, config );
                        
                                window.Misc.showAlertBox( _this.configAlert );
                                console.log('Backbone success');
                            },
                            error: function ( XMLHttpRequest, textStatus, errorThrown ) {
        
                                const text = 'Contacte con el administrador';
                                const type = 'alert';
                        
                                var config = {
                                    'text': text,
                                    'type': type
                                };
                        
                                _.extend( _this.configAlert, config );
                        
                                window.Misc.showAlertBox( _this.configAlert );
                                console.log('Backbone error');
                            }
        
                        });
                    }
                }
            });

            this.acceptConfirm.render();
        },

        // Modal confirm
        onModalConfirm: function (e) {
            e.preventDefault();
            this.projectModel = new app.ProjectModel();
            this.listenToOnce( this.projectModel, 'request', this.loadSpinner );

            var _this = this,
                action = $(e.currentTarget).attr('data-action'),
                project_name = $(e.currentTarget).attr('data-name'),
                data = {
                    'codigo_usuario': $(e.currentTarget).attr('data-id'),
                    'state': $(e.currentTarget).attr('data-state') == window._tp.getState['active'] ? window._tp.getState['inactive'] : window._tp.getState['active'],
                    'change_state': true
                };

            if( this.acceptConfirm instanceof Backbone.View ) {
                this.acceptConfirm.stopListening();
                this.acceptConfirm.undelegateEvents();
            }

            this.acceptConfirm = new app.ConfirmWindow({
                parameters: {
                    template: this.templateConfirm({
                        action : action,
                        project_name: project_name
                    }),
                    titleConfirm: "Confirmación",
                    onConfirm: function () {
                        _this.projectModel.save(data, {wait: true, patch: true,
                            success: function (model, resp) {
                                // complete proccess
                                window.Misc.removeSpinner({
                                    'wrap': _this.$el,
                                    'direct': false
                                });

                                // response success or error
                                var type = resp.success ? 'success' : 'alert',
                                    text = resp.success ?
                                        (resp.message !== undefined ? resp.message : '...')
                                        : resp.errors;

                                if( _.isObject( resp.errors ) ){

                                    var listError = '<ul>';

                                    $.each(resp.errors, function(field, item) {
                                         listError += '<li>'+ item[0] +'</li>';
                                    });
                                    listError += '</ul>';

                                    text = listError;
                                }

                                var config = {
                                    'text': text,
                                    'type': type
                                }
                                confCrop =  $.extend({}, _this.configAlert, config);

                                //complete proccess
                                if( resp.success !== undefined ){
                                    if( resp.success ){
                                        window.Misc.showAlertBox( confCrop );
                                        _this.projectsListSearchTable.ajax.reload( null, false );
                                    }else{
                                        window.Misc.showAlertBox( confCrop );
                                    }
                                }
                            }
                        });
                    }
                }
            });

            this.acceptConfirm.render();
        }
    });

})(jQuery, this, this.document);

/**
* Class OccupationCreateEditView extends of Backbone View
* @author TuProyecto || Desarrollador : @dortegon
* @link http://TuProyecto.com
*/

//Global App Backbone
app || (app = {});

(function ($, window, document, undefined) {

    app.OccupationCreateEditView = Backbone.View.extend({
        el: '#occupation-content',
        events: {
            'submit #form-occupation': 'addProfession'
        },
        parameters: {
            //
        },

        /**
        * Constructor Method
        */
        initialize: function(opts){

            // extends parameters
            if( opts.parameters !== undefined && _.isObject(opts.parameters) )
                this.parameters = $.extend({}, this.parameters, opts.parameters);

            //Init Attribute
            this.configAlert = {
                'wrapper': '#main-wrap',
                'closeTime': 6000,
                'speedOpen': 500,
                'speedClose': 500
            };

            // Events Listener
            this.listenTo( this.model, 'request', this.loadSpinner );
            this.listenTo( this.model, 'sync', this.responseServer );
        },

        /*
        * Render View Element
        */
        render: function() {
            // Reference to elements
            this.$formCreate = this.$('#form-occupation');
        },

        /**
        * Load spinner on the request
        */
        loadSpinner: function () {
            window.Misc.setSpinner( this.$('#section-content') );
        },

        /**
        * Add new occupation
        */
        addProfession: function (e) {
            e.preventDefault();

            var data = window.Misc.formToJson( e.target );
            this.model.save( data, {wait: true, patch:true} );
        },

        /**
        * response of the server
        */
        responseServer: function ( model, resp, opts ) {

            window.Misc.removeSpinner({
                wrap: this.$('#section-content'),
                direct: false
            });

            // response success or error
            var type = resp.success ? 'success' : 'alert',
                text = resp.success ?
                        (resp.message !== undefined ? resp.message : '...')
                            : resp.errors;

            if( _.isObject( resp.errors ) ) {

                var listError = '<ul>';

                $.each(resp.errors, function(field, item) {
                     listError += '<li>'+ item[0] +'</li>';
                });
                listError += '</ul>';

                text = listError;
            }

            var conf = {
                'text': text,
                'type': type
            };
            _.extend(this.configAlert, conf);

            //complete proccess
            if( resp.success !== undefined ) {
                if( resp.success ){
                    window.Misc.showAlertBox(this.configAlert);

                    if(resp.redirect){
                        window.Misc.redirect( app.AppRouter.navigate( Route.route('usuario.ocupacion.edit',{ocupacion: this.model.get('codigo_ocupacion_persona')}) ));
                    }
                }else {
                    window.Misc.showAlertBox(this.configAlert);
                    return false;
                }
            }
        }
    });
})(jQuery, this, this.document);

/**
* Class OccupationsListView extends of Backbone View
* @author TuProyecto || Desarrollador : @dortegon
* @link http://TuProyecto.com
*/

//Global App Backbone
app || (app = {});

(function ($, window, document, undefined) {

    app.OccupationsListView = Backbone.View.extend({

        el: '#occupation-content',
        template: _.template( ($('#occupation-list-tpl').html() || '') ),
        templateConfirm: _.template( ($('#confirm-occupation-tpl').html() || '') ),
        templateButtonsAction: _.template( ($('#buttons-action-tpl').html() || '') ),
        events: {
            'click .btn-search': 'search',
            'click .btn-clear': 'clear',
            'click .success': 'onModalConfirm',
            'click .danger': 'onModalConfirm'
        },
        parameters: {
            dataFilter: {}
        },

        /**
         * Constructor Method
         */
        initialize : function(opts) {

            // Events Listener custome
            this.on( 'beforeRender', this.beforeRender );
            this.on( 'afterRender', this.afterRender );

        },

        /*
         * Render View Element
         */
        render: function() {

            var attributes = {};
            this.$el.html( this.template(attributes) );

            // Initialize attributes
            this.$searchState   = this.$('#codigo_estado');
            this.$formFilters   = this.$('#form-occupation-filter');
            this.$searchNombre  = this.$('#nombre_ocupacion_persona');
            this.$occupationListSearchTable = this.$('#occupation-list-search-table');

            // overwrite model id attribute
            this.referenceViews();
        },

        /**
         * reference to views
         */
        referenceViews: function () {
            var _this = this;
            this.occupationListSearchTable = this.$occupationListSearchTable.DataTable({
                dom:"<'row'<'col-sm-5'i><'col-sm-7'p>>" +
                "<'row'<'col-sm-12'tr>>" +
                "<'row'<'col-sm-5'i><'col-sm-7'p>>",
                processing: true,
                serverSide: true,
                language: window.Misc.dataTableES(),
                ajax: {
                    url: window.Misc.urlFull( Route.route('usuario.ocupacion.index') ),
                    data: function( data ) {
                        data.nombre_ocupacion_persona   = _this.$searchNombre.val();
                        data.codigo_estado  = _this.$searchState.val();
                    },
                },
                columns: [
                    { data: 'nombre_ocupacion_persona', name: 'nombre_ocupacion_persona' }
                ],
                order: [
                    [ 0, 'asc' ]
                ],
                columnDefs: [
                    {
                        targets: 0,
                        render: function ( data, type, full, row ) {
                            return '<a href="' + window.Misc.urlFull(Route.route('usuario.ocupacion.edit', {ocupacion: full.codigo_ocupacion_persona}) ) + '" title="Ver ocupación" style="color:#3FC1A5">'+full.nombre_ocupacion_persona+'</a>';
                        }
                    },
                    {
                        targets: 1,
                        width: '10%',
                        orderable: false,
                        className: 'text-center',
                        render: function ( data, type, full, row ) {
                            return _this.templateButtonsAction( {full: full} )
                        }
                    }
                ]
            });
        },

        /**
        * Load spinner on the request
        */
        loadSpinner: function () {
            window.Misc.setSpinner( this.$gridSearchTable );
        },

        search: function(e) {
            e.preventDefault();
            this.occupationListSearchTable.ajax.reload();
        },

        clear: function(e) {
            e.preventDefault();

            this.$searchNombre.val('');
            this.$searchState.val('');

            this.occupationListSearchTable.ajax.reload();
        },

        // Modal confirm
        onModalConfirm: function (e) {
            e.preventDefault();
            this.occupationModel = new app.OccupationModel();
            this.listenToOnce( this.occupationModel, 'request', this.loadSpinner );

            var _this = this,
                action = $(e.currentTarget).attr('data-action'),
                occupation_name = $(e.currentTarget).attr('data-name'),
                data = {
                    'codigo_ocupacion_persona': $(e.currentTarget).data('id'),
                    'change_state': true
                };

            if( this.acceptConfirm instanceof Backbone.View ) {
                this.acceptConfirm.stopListening();
                this.acceptConfirm.undelegateEvents();
            }

            this.acceptConfirm = new app.ConfirmWindow({
                parameters: {
                    template: this.templateConfirm({
                        action : action,
                        occupation_name: occupation_name
                    }),
                    titleConfirm: "Confirmación",
                    onConfirm: function () {
                        _this.occupationModel.save(data, {wait: true, patch: true,
                            success: function (model, resp) {
                                // complete proccess
                                window.Misc.removeSpinner({
                                    'wrap': _this.$el,
                                    'direct': false
                                });

                                // response success or error
                                var type = resp.success ? 'success' : 'alert',
                                    text = resp.success ?
                                        (resp.message !== undefined ? resp.message : '...')
                                        : resp.errors;

                                if( _.isObject( resp.errors ) ){

                                    var listError = '<ul>';

                                    $.each(resp.errors, function(field, item) {
                                         listError += '<li>'+ item[0] +'</li>';
                                    });
                                    listError += '</ul>';

                                    text = listError;
                                }

                                var config = {
                                    'text': text,
                                    'type': type
                                }
                                confCrop =  $.extend({}, _this.configAlert, config);

                                //complete proccess
                                if( resp.success !== undefined ){
                                    if( resp.success ){
                                        window.Misc.showAlertBox( confCrop );
                                        _this.occupationListSearchTable.ajax.reload( null, false );
                                    }else{
                                        window.Misc.showAlertBox( confCrop );
                                    }
                                }
                            }
                        });
                    }
                }
            });

            this.acceptConfirm.render();
        }
    });

})(jQuery, this, this.document);

